  if(!previousRemoved)S.removedSourceIds=S.removedSourceIds.filter(id=>id!==d.id);
  saveSession();
  say('Front/Back सेव हैं, लेकिन A4 लेआउट में कार्ड नहीं बने। Sheet Size A4, Card Size और Image Layout जाँचें।');
  return false;
