let sheetZoom=1,baseSheetSize=null;const updateSheetZoom=()=>{const sheet=$('sheetPreview'),stage=$('sheetStage');if(!baseSheetSize){baseSheetSize={width:sheet.offsetWidth,height:sheet.offsetHeight};sheet.style.width=baseSheetSize.width+'px';sheet.style.height=baseSheetSize.height+'px';}sheet.style.zoom='1';sheet.style.transform='translateZ(0) scale('+sheetZoom+')';sheet.style.transformOrigin='top left';stage.style.width=(baseSheetSize.width*sheetZoom)+'px';stage.style.height=(baseSheetSize.height*sheetZoom)+'px';$('sheetZoomReset').textContent=Math.round(sheetZoom*100)+'%';const slider=$('sheetZoomSlider');if(slider)slider.value=String(Math.round(sheetZoom*100));};const setSheetZoom=z=>{sheetZoom=Math.max(.5,Math.min(3,z));updateSheetZoom();};$('sheetZoomIn').onclick=()=>setSheetZoom(sheetZoom+.25);$('sheetZoomOut').onclick=()=>setSheetZoom(sheetZoom-.25);$('sheetZoomReset').onclick=()=>setSheetZoom(1);const slider=$('sheetZoomSlider');if(slider)slider.oninput=e=>setSheetZoom(Number(e.target.value)/100);const wrap=$('previewWrap');if(wrap)wrap.addEventListener('wheel',e=>{if(e.defaultPrevented)return;e.preventDefault();setSheetZoom(sheetZoom*(e.deltaY<0?1.18:1/1.18));},{passive:false});const sheet=$('sheetPreview');sheet.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';});sheet.addEventListener('drop',e=>{e.preventDefault();const index=Number(e.dataTransfer.getData('text/plain'));if(Number.isInteger(index)&&S.docs[index])placeSourceOnSheet(index,e.clientX,e.clientY);});$('chooseFiles').onclick=()=>$('upload').click();$('upload').onchange=e=>importFiles(e.target.files);$('prev').onclick=()=>setDoc(S.docIndex-1);$('next').onclick=()=>setDoc(S.docIndex+1);$('clearCrop').onclick=()=>{S.selection=null;$('cropBox').style.display='none';};$('sourceZoomIn').onclick=()=>{S.sourceZoom=Math.min(3,Math.round((S.sourceZoom+.25)*100)/100);updateSourceZoom();};$('sourceZoomOut').onclick=()=>{S.sourceZoom=Math.max(.75,Math.round((S.sourceZoom-.25)*100)/100);updateSourceZoom();};$('sourceZoomReset').onclick=()=>{S.sourceZoom=1;updateSourceZoom();};$('sheetUndo').onclick=undoSheet;$('sheetRedo').onclick=redoSheet;updateHistoryButtons();$('applyPlacedCrop').onclick=applyPlacedCrop;$('cancelPlacedCrop').onclick=finishPlacedCrop;$('closeCropWorkspace').onclick=closeCropWorkspace;$('cancelCropWorkspace').onclick=closeCropWorkspace;$('cropFrontSide').onclick=()=>setCropWorkspaceSide('front');$('cropBackSide').onclick=()=>setCropWorkspaceSide('back');document.querySelectorAll('input[name="cropSide"]').forEach(r=>r.addEventListener('change',()=>{if($('cropWorkspace')?.classList.contains('open')){S.selection=null;$('cropBox').style.display='none';syncCropWorkspaceSide();drawCropWorkspaceSourceSide();drawCropWorkspacePreview();saveSession();}}));$('confirmCropWorkspace').onclick=(e)=>{e.preventDefault();const note=$('cropWorkspaceSaveStatus');try{const saved=saveWorkspaceSide();if(note)note.textContent=saved?'✓ '+activeSide().toUpperCase()+' क्रॉप सेव हो गया। अब दूसरी साइड चुनें।':'पहले फोटो पर क्रॉप बॉक्स खींचें, फिर सेव करें।';}catch(err){console.error('Crop Workspace save failed',err);if(note)note.textContent='सेव नहीं हुआ: '+(err?.message||'अंदरूनी त्रुटि')+'. फिर कोशिश करें।';}};$('applyCropWorkspace').onclick=applyCropWorkspace;$('cropWorkspace').addEventListener('click',e=>{if(e.target===$('cropWorkspace'))closeCropWorkspace();});$('mode').onchange=()=>{setMode();if(S.crops.length)buildSheets();};$('autoPrepare').onclick=autoPrepare;

